fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    let n_usize = n as usize;
    let k_i16 = k as i16;

    let eligible = participations
        .iter()
        .take(n_usize)
        .filter(|&&p| (5i16 - p as i16) >= k_i16)
        .count() as u8;

    eligible / 3
}